            me->RemoveAurasDueToSpell(SPELL_RAGNAROK_MOD);
            aegisEvent = false;
            powerTimer = 1000;

            if (!intro)
            {
                AddDelayedEvent(10000, [=] () -> void
                {
                    me->RemoveFlag(UNIT_FIELD_FLAGS, UNIT_FLAG_IMMUNE_TO_NPC | UNIT_FLAG_IMMUNE_TO_PC | UNIT_FLAG_NON_ATTACKABLE);
                    me->SetReactState(REACT_DEFENSIVE);
                });

                if (auto odyn = instance->instance->GetCreature(instance->GetGuidData(DATA_ODYN)))
                    odyn->CastSpell(odyn, SPELL_AEGIS_SPAWN, true);
            }
