                caller->setFaction(16);
                caller->AI()->DoZoneInCombat(caller, 100.0f);

                if (KingGUIDs.size() == 1)
                {
                    for (auto guid : KingGUIDs)
                    {
                        if (Creature* King = Creature::GetCreature(*me, guid))
                        {
                            King->setFaction(16);
                            King->AI()->DoZoneInCombat(King, 100.0f);
