        {
            if (!apply || passenger == nullptr)
                return;

            if (!attumenSpawnRide && passenger->GetEntry() == NPC_ATTUMEN_THE_HUNTSMAN)
            {
                attumenSpawnRide = true;
                me->RemoveFlag(UNIT_FIELD_FLAGS, UNIT_FLAG_IMMUNE_TO_PC | UNIT_FLAG_IMMUNE_TO_NPC | UNIT_FLAG_NOT_ATTACKABLE_1 | UNIT_FLAG_NOT_SELECTABLE);
